#!/usr/bin/env node
/* global console, process */
/**
 * Sitemap sync guard — public/sitemap.xml is generated by
 * scripts/generateSitemap.mjs from the prerender route list; this test fails
 * CI when the checked-in file drifts from a fresh build (someone hand-edited
 * it, or added a blog post / public route without running `npm run sitemap`).
 *
 * Also pins the generator's own invariants:
 *   - every prerendered route (+ the homepage) is advertised, and nothing else
 *   - every blog post carries a <lastmod> from its frontmatter
 *   - every emitted <lastmod> is a plain YYYY-MM-DD date
 *
 * Run: npm run test:sitemap-sync   (also via npm run test:all)
 */
import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { buildSitemapXml } from './generateSitemap.mjs'
import { buildRouteList, discoverBlogSlugs } from './prerenderRoutes.mjs'

const __dirname = dirname(fileURLToPath(import.meta.url))
const root = join(__dirname, '..')

let pass = 0
let fail = 0
const failures = []

function test(name, fn) {
  try {
    fn()
    pass++
    console.log(`  ok  ${name}`)
  } catch (err) {
    fail++
    failures.push({ name, message: err.message })
    console.log(`  FAIL ${name}`)
    console.log(`       ${err.message}`)
  }
}

function assert(cond, msg) {
  if (!cond) throw new Error(msg)
}

const generated = buildSitemapXml()
const checkedIn = readFileSync(join(root, 'public', 'sitemap.xml'), 'utf8')

console.log('\nsitemap.xml stays in sync with the generator')

test('checked-in public/sitemap.xml matches a fresh generator run', () => {
  assert(
    checkedIn === generated,
    'public/sitemap.xml differs from generateSitemap.mjs output — run `npm run sitemap` '
      + 'and commit the result (never hand-edit the file).',
  )
})

const locs = [...generated.matchAll(/<loc>\s*([^<]+?)\s*<\/loc>/g)].map(
  (m) => m[1].replace(/^https?:\/\/[^/]+/, '') || '/',
)

test('advertised URL set is exactly {"/"} ∪ buildRouteList()', () => {
  const expected = new Set(['/', ...buildRouteList()])
  const actual = new Set(locs)
  const missing = [...expected].filter((p) => !actual.has(p))
  const extra = [...actual].filter((p) => !expected.has(p))
  assert(
    missing.length === 0 && extra.length === 0,
    `sitemap URL set drifted — missing: [${missing.join(', ')}] extra: [${extra.join(', ')}]`,
  )
})

test('every blog post entry has a <lastmod>', () => {
  for (const slug of discoverBlogSlugs()) {
    const entry = generated.split('<url>').find((c) => c.includes(`/blog/${slug}<`))
    assert(entry, `/blog/${slug} missing from sitemap`)
    assert(
      /<lastmod>\d{4}-\d{2}-\d{2}<\/lastmod>/.test(entry),
      `/blog/${slug} has no <lastmod> — its markdown frontmatter needs a publishedAt date`,
    )
  }
})

test('every <lastmod> is a plain YYYY-MM-DD date', () => {
  for (const [, v] of generated.matchAll(/<lastmod>([^<]*)<\/lastmod>/g)) {
    assert(/^\d{4}-\d{2}-\d{2}$/.test(v), `bad lastmod value "${v}"`)
  }
})

console.log(`\n${pass} passed, ${fail} failed`)
if (fail > 0) {
  console.log('\nFailures:')
  for (const f of failures) console.log(`  - ${f.name}: ${f.message}`)
  process.exit(1)
}
